import { useTheme } from '@crossbuildui/core'; // Adjust path
import { BlurView } from 'expo-blur';
import { LinearGradient } from 'expo-linear-gradient';
import React, { useEffect } from 'react';
import { Platform, StyleProp, StyleSheet, View, ViewStyle } from 'react-native';
import Animated, {
    Easing,
    interpolate,
    useAnimatedProps,
    useAnimatedStyle,
    useSharedValue,
    withRepeat,
    withTiming,
} from 'react-native-reanimated';
import type { SkeletonProps } from './types';

const AnimatedBlurView = Animated.createAnimatedComponent(BlurView);

const Skeleton: React.FC<SkeletonProps> = ({
    children,
    isLoaded = false,
    disableAnimation = false,
    style: placeholderStyleProp, // This style defines the skeleton's shape
    styles: slotStylesProp,
    shimmerColor: customShimmerColor,
    placeholderBackgroundColor: customPlaceholderBgColor,
    isGlass = false,
    glassTint: propGlassTint,
    glassIntensity = 30,
}) => {
    const { colors: themeColors, mode } = useTheme();
    const progress = useSharedValue(0);

    let placeholderBg = customPlaceholderBgColor || (mode === 'dark' ? themeColors.default['200'] : themeColors.default['100']);
    if (isGlass) {
        placeholderBg = 'transparent'; // BlurView will provide the background
    }

    // Shimmer color: semi-transparent white/light gray for light mode, darker for dark mode
    const shimmerColor = customShimmerColor || (isGlass ? (mode === 'dark' ? 'rgba(255, 255, 255, 0.15)' : 'rgba(0, 0, 0, 0.08)') : (mode === 'dark' ? 'rgba(255, 255, 255, 0.1)' : 'rgba(255, 255, 255, 0.3)'));
    const shimmerBg = customShimmerColor ? customShimmerColor.replace('rgba', 'rgb').replace(/,[^,]*\)/, ')') : (mode === 'dark' ? 'rgba(100,100,100,0.1)' : 'rgba(200,200,200,0.2)');


    useEffect(() => {
        if (!isLoaded && !disableAnimation) {
            progress.value = withRepeat(
                withTiming(1, { duration: 1200, easing: Easing.inOut(Easing.ease) }),
                -1, // Infinite repeat
                false // Don't reverse
            );
        } else {
            progress.value = 0; // Reset or stop animation
        }
    }, [isLoaded, disableAnimation, progress]);

    const animatedShimmerStyle = useAnimatedStyle(() => {
        const translateX = interpolate(
            progress.value,
            [0, 1],
            [-200, 400] // Adjust these values based on typical skeleton width for a good sweep
        );
        return {
            transform: [{ translateX }],
        };
    });

    const animatedGlassIntensityProps = useAnimatedProps(() => {
        // Create a pulsing effect for intensity.
        // progress.value goes 0 -> 1, then repeats.
        // Interpolate so intensity goes: base -> peak -> base over one cycle.
        const peakIntensityDelta = 20; // How much the intensity increases at the peak.
        const currentIntensity = interpolate(
            progress.value,
            [0, 0.5, 1],
            [glassIntensity, glassIntensity + peakIntensityDelta, glassIntensity],
        );
        return { intensity: currentIntensity };
    });

    if (isLoaded) {
        return <>{children}</>;
    }

    const placeholderStyle: StyleProp<ViewStyle> = [
        styles.placeholderBase,
        { backgroundColor: placeholderBg },
        placeholderStyleProp, // User-defined shape and size
        slotStylesProp?.placeholder,
    ];

    const shimmerStyle: StyleProp<ViewStyle> = [
        styles.shimmerBase,
        slotStylesProp?.shimmer,
    ];

    const effectiveGlassTint = propGlassTint || (mode === 'light' ? 'light' : 'dark');
    const flatPlaceholderStyle = StyleSheet.flatten(placeholderStyle); // To access borderRadius

    return (
        <View style={placeholderStyle}>
            {isGlass ? (
                disableAnimation ? (
                    <BlurView
                        style={[
                            StyleSheet.absoluteFillObject,
                            { borderRadius: flatPlaceholderStyle.borderRadius },
                            Platform.OS === 'android' && { backgroundColor: effectiveGlassTint === 'dark' ? 'rgba(0,0,0,0.2)' : 'rgba(255,255,255,0.2)' }
                        ]}
                        tint={effectiveGlassTint}
                        intensity={glassIntensity}
                        {...(Platform.OS === 'android' && { experimentalBlurMethod: 'dimezisBlurView' })}
                    />
                ) : (
                    <AnimatedBlurView
                        style={[
                            StyleSheet.absoluteFillObject,
                            { borderRadius: flatPlaceholderStyle.borderRadius },
                            Platform.OS === 'android' && { backgroundColor: effectiveGlassTint === 'dark' ? 'rgba(0,0,0,0.2)' : 'rgba(255,255,255,0.2)' }
                        ]}
                        tint={effectiveGlassTint}
                        animatedProps={animatedGlassIntensityProps}
                        {...(Platform.OS === 'android' && { experimentalBlurMethod: 'dimezisBlurView' })}
                    />
                )
            ) : (!disableAnimation && (
                <Animated.View style={[StyleSheet.absoluteFill, animatedShimmerStyle, { zIndex: 1 }]}>
                    <LinearGradient
                        colors={[`${placeholderBg}00`, shimmerColor, `${placeholderBg}00`]} // Transparent -> Shimmer -> Transparent
                        start={{ x: 0, y: 0.5 }}
                        end={{ x: 1, y: 0.5 }}
                        style={shimmerStyle}
                    />
                </Animated.View>
            ))}
        </View>
    );
};

const styles = StyleSheet.create({
    placeholderBase: {
        overflow: 'hidden', // Important to clip the shimmer
        // Default width/height if not provided by user style, though user style is expected
        // width: '100%',
        // height: 20, // A small default height
        // borderRadius: 4, // Default radius
    },
    shimmerBase: {
        width: '200%', // Make shimmer wider than placeholder to sweep across
        height: '100%',
    },
});

export default Skeleton;